text:
Provider listo para Next.js App Router, Lenis y `ScrollTrigger`:

```tsx
// app/providers/smooth-scroll-provider.tsx
"use client";

import type { PropsWithChildren } from "react";
import { useCallback, useEffect } from "react";
import { ReactLenis, useLenis } from "lenis/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

function ScrollTriggerBridge() {
  const handleScroll = useCallback(() => {
    ScrollTrigger.update();
  }, []);

  const lenis = useLenis(handleScroll);

  useEffect(() => {
    if (!lenis) return;

    gsap.registerPlugin(ScrollTrigger);

    const updateLenis = (time: number) => {
      // GSAP entrega segundos; Lenis espera milisegundos.
      lenis.raf(time * 1000);
    };

    gsap.ticker.add(updateLenis);
    gsap.ticker.lagSmoothing(0);
    ScrollTrigger.refresh();

    return () => {
      gsap.ticker.remove(updateLenis);
    };
  }, [lenis]);

  return null;
}

export function SmoothScrollProvider({
  children,
}: PropsWithChildren) {
  return (
    <ReactLenis
      root
      options={{
        autoRaf: false,
        smoothWheel: true,
        anchors: true,
      }}
    >
      <ScrollTriggerBridge />
      {children}
    </ReactLenis>
  );
}
```

Móntalo en el layout raíz:

```tsx
// app/layout.tsx
import { SmoothScrollProvider } from "./providers/smooth-scroll-provider";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="es">
      <body>
        <SmoothScrollProvider>
          {children}
        </SmoothScrollProvider>
      </body>
    </html>
  );
}
```

Y en `app/globals.css`:

```css
@import "lenis/dist/lenis.css";
```

No hace falta `scrollerProxy`: Lenis conserva el scroll nativo y sincroniza `ScrollTrigger` mediante `ScrollTrigger.update()`. `autoRaf: false` evita ejecutar dos bucles de animación, dejando a `gsap.ticker` como reloj único.
